import { Component, viewChild, ElementRef } from '@angular/core';

@Component({
  selector: 'app-search',
  template: `
    <input #box>
    <button (click)="focus()">Focus</button>`
})
export class Search {
  box = viewChild<ElementRef>('box');
  focus() {
    this.box()?.nativeElement.focus();
  }
}
